    A=[[Fraction(x) for x in row] for row in m]
    swaps=0
    for k in range(n):
        piv=-1
        for i in range(k,n):
            if A[i][k]!=0:
                piv=i
                break
        if piv==-1:
            return 0
        if piv!=k:
            A[k],A[piv]=A[piv],A[k]
            swaps+=1
        akk=A[k][k]
        for i in range(k+1,n):
            factor=A[i][k]/akk
            if factor!=0:
                for j in range(k,n):
                    A[i][j]-=factor*A[k][j]
    d=Fraction(1)
