def solve(m):
    n = len(m)
    if n == 0:
        return 1
    if n == 1:
        return m[0][0]
    # cofactor expansion along first row
    total = 0
    for j in range(n):
        sub = [row[:j] + row[j+1:] for row in m[1:]]
        sign = -1 if j % 2 else 1
        total += sign * m[0][j] * solve(sub)
    return total

